const collections=[{id:'kybalion',name:'THE KYBALION',line:'SEVEN PRINCIPLES. ONE INNER WORLD.',symbol:'YELLOW INK / PHILOSOPHY',description:'Seven philosophical principles translated into original black-and-yellow letterwork and geometric imagery. A contemporary artistic reading of The Kybalion.'},{id:'shadow',name:'SHADOW WORK',line:'MEET THE PARTS YOU HIDE.',symbol:'SHADOW / INTROSPECTION',description:'An illustrated study of inner work. Bold ink, a divided face and open geometry invite a closer look at what sits beneath the surface.'},{id:'transmute',name:'AS ABOVE / SO BELOW',line:'CHANGE BEGINS WITHIN.',symbol:'CONTRAST / TRANSFORMATION',description:'Mirrored architecture and paired triangles become a creative metaphor for correspondence, connecting an inner reading with the city outside.'}];
const products=document.querySelector('#products');function render(filter='all'){products.innerHTML=collections.filter(p=>filter==='all'||p.id===filter).map(p=>`<article class="product-card"><button data-detail="${p.id}" aria-label="Explore ${p.name}"><span class="tag">COLLECTION STUDY</span><img loading="lazy" src="/assets/masterworks-v2/${({'kybalion':'028','shadow':'033','transmute':'072'}[p.id]||'002')}.webp" alt="Illustrative ${p.name} graphic-novel artwork"><span class="product-arrow">↗</span></button><div class="product-meta"><div><h3>${p.name}</h3><p>${p.line}</p></div><span>0${collections.indexOf(p)+1}</span></div></article>`).join('')};render();
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render(b.dataset.filter)}));
const modal=document.querySelector('#detail'),content=document.querySelector('#detail-body');function open(html){content.innerHTML=html;modal.showModal()}document.querySelector('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
products.addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(!b)return;const p=collections.find(x=>x.id===b.dataset.detail);open(`<div class="detail-grid"><img src="/assets/masterworks-v2/${({'kybalion':'028','shadow':'033','transmute':'072'}[p.id]||'002')}.webp" alt="${p.name} illustrative concept"><div><span class="eyebrow">${p.symbol}</span><h2>${p.name}</h2><p>${p.description}</p><p>Design concept. This preview does not confirm a product SKU, price, edition size, stock or Printful availability. Browse the original collection. Sales are not open yet.</p><a class="button" target="_blank" rel="noopener" href="/shop/">VIEW THE COLLECTION ↗</a></div></div>`)});
document.querySelectorAll('[data-art]').forEach(b=>b.onclick=()=>{document.querySelector('#garment').src=`/assets/masterworks-v2/${({'kybalion':'028','shadow':'033','transmute':'072'}[b.dataset.art]||'002')}.webp`;document.querySelector('#garment').alt=`Illustrative ${b.dataset.art} graphic-novel artwork`;document.querySelectorAll('[data-art]').forEach(x=>x.classList.toggle('active',x===b))});
const principles=[['I','MENTALISM','It starts in the mind.','The first principle places mind at the centre of experience. Our interpretation: examine the story you tell yourself before you let it shape your world.'],['II','CORRESPONDENCE','Look within. Look around.','As above, so below. The collection interprets correspondence through mirrored triangles: an invitation to notice patterns across different scales of life.'],['III','VIBRATION','Nothing stands still.','Vibration describes a universe in motion. In this collection, the symbol becomes a reminder that your perspective can move too.'],['IV','POLARITY','Hold both sides.','Opposites become a way to consider a spectrum. Light and shadow, stillness and movement: the design asks what becomes visible when you hold both.'],['V','RHYTHM','Find your own rhythm.','The imagery of cycles and returning movement becomes a prompt to observe your habits, seasons and pace.'],['VI','CAUSE & EFFECT','Choose your next move.','Every action has consequences. Here the principle becomes a practical question: what are you setting in motion today?'],['VII','GENERATION','Make something real.','The historical principle of gender is interpreted here through creative and receptive qualities. It is a philosophical motif, not a biological or scientific claim.']];
document.querySelector('#principles').innerHTML=principles.map((p,i)=>`<button class="${i===0?'selected':''}" data-principle="${i}" aria-label="${p[1]}">${p[0]}</button>`).join('');document.querySelectorAll('[data-principle]').forEach(b=>b.onclick=()=>{const p=principles[+b.dataset.principle];document.querySelector('#principle-number').textContent=`${p[0]} / ${p[1]}`;document.querySelector('#principle-title').textContent=p[2];document.querySelector('#principle-body').textContent=p[3];document.querySelectorAll('[data-principle]').forEach(x=>x.classList.toggle('selected',x===b))});
const campaigns=['transmute','mentalism','correspondence','vibration','polarity','rhythm','cause-effect','generation','shadow-work','as-above','so-below','underground'];document.querySelector('#sticker-open').onclick=()=>open(`<span class="eyebrow">THE STREET SERIES / 12 PORTALS</span><h2>LEAVE A SIGN.</h2><p>Download vector QR artwork. Each code includes its campaign parameters and links to the public CAISIK Site. Verify the final printed code at actual size before distribution.</p><div class="qr-grid">${campaigns.map((c,i)=>`<a href="/assets/qr-${c}.svg" download="caisik-${c}.svg"><b>${String(i+1).padStart(2,'0')} / ${c.toUpperCase()}</b><img src="/assets/qr-${c}.svg" alt="Download QR code for ${c}"><small>DOWNLOAD VECTOR SVG ↓</small></a>`).join('')}</div>`);
document.querySelector('#privacy-open').onclick=()=>open(`<span class="eyebrow">PROJECT STATUS / OCTOBER 2026</span><h2>TRANSPARENT BY DESIGN.</h2><p>This Site combines a verified public product-catalog snapshot with clearly marked illustrative collection studies. Educational lessons, interactive metaphors and local tools are also included.</p><p>The previous Magento GraphQL queries returned zero products. A separate verified public catalog from hiphop.caisik.i234.me is now shown above the illustrative collections. Links open the original CAISIK store. Cart, checkout, payment, order sync and Printful fulfillment have not been integrated or tested here.</p><p>No analytics, tracking cookies or email collection is implemented. Wishlist, discovered QR symbols, theme, motion setting and editorial preferences and learning progress may be stored locally in this browser. You can clear them below. QR URLs include campaign parameters; scans and sales are not measured. Google Fonts may make external requests. The Sites host and the external original CAISIK store apply their own privacy practices.</p><p>The QR destinations link to the public CAISIK Site. A physical print proof and scan check are still required before distribution.</p>`);
const path=location.pathname.split('/').filter(Boolean);if(path[0]==='q'){const slug=path[1];if(campaigns.includes(slug)){document.querySelector('#portal').hidden=false;document.querySelector('#portal-title').textContent=slug.replaceAll('-',' ').toUpperCase();document.title=`${slug.toUpperCase()} — CAISIK`;document.querySelector('main').setAttribute('inert','');document.querySelector('header').setAttribute('inert','')}}
// Scroll-driven layered perspective: one RAF per input burst; no idle animation loop.
const motion=matchMedia('(prefers-reduced-motion: reduce)');const compactStory=matchMedia('(max-width: 768px)');const track=document.querySelector('.story-track'),chapters=[...document.querySelectorAll('.story-chapter')],stage=document.querySelector('.story-stage'),storyGarment=document.querySelector('.story-garment'),sigil=document.querySelector('.story-sigil'),giant=document.querySelector('.story-giant');let queued=false,lastChapter=-1;const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));function updateMotion(){queued=false;const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.page-progress').style.transform=`scaleX(${max>0?scrollY/max:0})`;if(motion.matches||document.body.classList.contains('simple-mode')||compactStory.matches){chapters.forEach(c=>c.inert=false);lastChapter=-1;document.querySelector('.hero-art').style.transform='none';document.querySelector('.hero-graffiti').style.translate='none';if(compactStory.matches)document.querySelector('#story-count').textContent='03 CHAPTERS';return;}const r=track.getBoundingClientRect(),progress=clamp(-r.top/Math.max(1,r.height-innerHeight),0,1);const chapter=Math.min(2,Math.floor(progress*3));if(lastChapter!==chapter){chapters.forEach((x,i)=>{x.classList.toggle('is-active',i===chapter);x.inert=i!==chapter});lastChapter=chapter;document.querySelector('#story-count').textContent=`0${chapter+1} — 03`;storyGarment.src=`/assets/masterworks-v2/${({'kybalion':'028','shadow':'033','transmute':'072'}[['kybalion','shadow','transmute'][chapter]]||'002')}.webp`;giant.textContent=['SOLVE','SHADOW','COAGULA'][chapter]}if(r.top<innerHeight&&r.bottom>0){storyGarment.style.transform=`translate3d(${Math.sin(progress*Math.PI*2)*30}px,${(progress-.5)*-80}px,${70+Math.sin(progress*Math.PI)*100}px) rotateY(${(progress-.5)*46}deg) rotateZ(${-8+progress*16}deg)`;sigil.style.transform=`translateZ(-60px) rotate(${progress*150}deg) scale(${.85+progress*.45})`;giant.style.transform=`translate3d(${-progress*150}px,0,-130px)`;document.querySelector('.story-grid').style.transform=`rotateX(65deg) translateY(${progress*110}px)`;document.querySelector('.story-atmosphere').style.filter=`hue-rotate(${progress* -22}deg)`}document.querySelector('.story-progress i').style.transform=`scaleX(${progress})`;const hero=document.querySelector('.hero');if(hero.getBoundingClientRect().bottom>0){const v=clamp(scrollY/900,0,1);document.querySelector('.hero-art').style.transform=`translate3d(0,${v*80}px,0) rotateY(${-v*12}deg)`;document.querySelector('.hero-graffiti').style.translate=`0 ${-v*50}px`}}function requestMotion(){if(!queued){queued=true;requestAnimationFrame(updateMotion)}}addEventListener('scroll',requestMotion,{passive:true});addEventListener('resize',()=>{lastChapter=-1;requestMotion()});compactStory.addEventListener('change',()=>{lastChapter=-1;chapters.forEach(c=>c.inert=false);requestMotion()});motion.addEventListener('change',()=>{lastChapter=-1;if(motion.matches){chapters.forEach(c=>c.inert=false);document.querySelector('.hero-art').style.transform='none';document.querySelector('.hero-graffiti').style.translate='none'}requestMotion()});updateMotion();
const revealObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('in-view');revealObserver.unobserve(entry.target)}},{threshold:.12});document.querySelectorAll('.section-head,.street-grid,.manifesto>div,.closing h2').forEach(el=>{el.classList.add('reveal-ready');revealObserver.observe(el)});if(matchMedia('(hover:hover) and (pointer:fine)').matches){products.addEventListener('pointermove',e=>{if(motion.matches||document.body.classList.contains('simple-mode'))return;const card=e.target.closest('.product-card button');if(!card)return;const r=card.getBoundingClientRect();card.style.transform=`rotateX(${-(e.clientY-r.top-r.height/2)/r.height*10}deg) rotateY(${(e.clientX-r.left-r.width/2)/r.width*12}deg)`});products.addEventListener('pointerout',e=>{const card=e.target.closest('.product-card button');if(card&&!card.contains(e.relatedTarget))card.style.transform='none'});const scene=document.querySelector('.sticker-scene');scene.addEventListener('pointermove',e=>{if(motion.matches||document.body.classList.contains('simple-mode'))return;const r=scene.getBoundingClientRect();scene.querySelector('.sticker').style.transform=`rotate(-9deg) rotateY(${(e.clientX-r.left-r.width/2)/r.width*25}deg) rotateX(${-(e.clientY-r.top-r.height/2)/r.height*20}deg) translateZ(40px)`});scene.addEventListener('pointerleave',()=>scene.querySelector('.sticker').style.transform='rotate(-9deg)')}
